{
  "requirement_id": "REQ-006",
  "cases": [
    {
      "id": "TC-1",
      "title": "Assign task to a non-project member",
      "surface": "api",
      "steps": [
        "Create a project as alice",
        "Create a task in the project",
        "Send PATCH /api/tasks/{tid} with assignee_id set to bob (who is not a project member) using header X-User: alice"
      ],
      "expected": "指派對象必須是該專案成員；否則回傳 422 錯誤，且任務 assignee 保持不變"
    },
    {
      "id": "TC-2",
      "title": "Assign task to a non-existent user",
      "surface": "api",
      "steps": [
        "Create a project as alice",
        "Create a task in the project",
        "Send PATCH /api/tasks/{tid} with assignee_id set to a non-existent user ID using header X-User: alice"
      ],
      "expected": "指派不存在的使用者時，回傳 422 錯誤"
    }
  ]
}

